const LINE = "exec(open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'recycle.py'), encoding='utf-8').read())\n"
const editsFile = path.join(root, 'src', 'game', 'mod', 'edits.json')
const patchFile = path.join(root, 'tools', 'game-mod', 'patch.py')
const indexFile = path.join(root, 'src', 'game', 'surfaces', 'index.js')
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b)

function setSteps (E, steps) {
  const old = E.id
  E.files[REL] = steps
  const { id, ...body } = E
  E.id = crypto.createHash('sha1').update(JSON.stringify(body, null, 1)).digest('hex').slice(0, 10)
  fs.writeFileSync(editsFile, JSON.stringify(E, null, 1) + '\n')
  return `${old} -> ${E.id}`
}

// Presets stays by the close button (JR's own place).
function presetsLeft () {
  const ix = fs.existsSync(indexFile) ? fs.readFileSync(indexFile, 'utf8') : ''
  if (/recycle: \{ pos: 'right' \}/.test(ix)) {
    fs.writeFileSync(indexFile, ix.replace(/recycle: \{ pos: 'right' \}/, "recycle: { pos: 'left' }"))
    console.log('  index.js: Presets back on the top bar, by the X')
  } else console.log('  index.js: Presets already by the X')
}

console.log('JR folder: ' + root)
const E = JSON.parse(fs.readFileSync(editsFile, 'utf8'))
if (!E.files || !E.files[REL]) throw new Error(`${REL} is missing from edits.json: is this the JR folder?`)
const now = E.files[REL]

if (same(now, V2_STEPS)) console.log('  edits.json: already the newest recycle version (' + E.id + ')')
else if (same(now, JR_STEPS) || same(now, V1_STEPS)) console.log('  edits.json updated (' + setSteps(E, V2_STEPS) + ')')
else throw new Error(`${REL} in edits.json has changes this script doesn't know. Nothing was changed.`)

if (!fs.existsSync(path.join(root, 'tools', 'game-mod', 'recycle.py'))) console.log('  WARNING: tools/game-mod/recycle.py is missing (the game does not need it; the next developer build does).')
if (fs.existsSync(patchFile)) {
  let py = fs.readFileSync(patchFile, 'utf8')
  if (py.includes(LINE)) console.log('  patch.py already runs recycle.py')
  else {
    const at = py.lastIndexOf("print('ok')")
    py = at >= 0 ? py.slice(0, at) + LINE + py.slice(at) : py + (py.endsWith('\n') ? '' : '\n') + LINE
    fs.writeFileSync(patchFile, py)
    console.log('  patch.py now runs recycle.py')
  }
} else console.log('  patch.py: not there (the game does not need it)')
presetsLeft()
console.log('Done. Start JR, press Play, log in, and leave JR open until the log says the in-game features are ready.')
